thm proposition_24_semicircle_use:
    ? exist o, a, b, translation cart(R, R), co, si, orientation R st {o = (0, 0), a = (1, 0), b = (-1, 0), $f2::are_similar_circular_segments(o, a, b, o, a, b, 1, 1, 1, -1), $f2::is_plane_rigid_motion_between_regions(f2::circular_segment_region(o, a, b, 1, 1), f2::circular_segment_region(o, a, b, 1, -1), translation, co, si, orientation)}
    release thm opposite_semicircular_segments_similar_use
    obtain o, a, b from exist oo, aa, bb cart(R, R) st {oo = (0, 0), aa = (1, 0), bb = (-1, 0), $f2::are_similar_circular_segments(oo, aa, bb, oo, aa, bb, 1, 1, 1, -1)}
    release thm proposition_24(o, a, b, o, a, b, 1, 1, 1, -1)
    obtain translation, co, si, orientation from exist t cart(R, R), h, k, orientation_sign R st {$f2::is_plane_rigid_motion_between_regions(f2::circular_segment_region(o, a, b, 1, 1), f2::circular_segment_region(o, a, b, 1, -1), t, h, k, orientation_sign)}
    witness exist oo, aa, bb, t cart(R, R), h, k, orientation_sign R st {oo = (0, 0), aa = (1, 0), bb = (-1, 0), $f2::are_similar_circular_segments(oo, aa, bb, oo, aa, bb, 1, 1, 1, -1), $f2::is_plane_rigid_motion_between_regions(f2::circular_segment_region(oo, aa, bb, 1, 1), f2::circular_segment_region(oo, aa, bb, 1, -1), t, h, k, orientation_sign)} from o, a, b, translation, co, si, orientation
